using System;using System.IO;using System.Linq;using System.Collections;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using NarutoVR.QingGuiR03Review;using Object=UnityEngine.Object;
[InitializeOnLoad] public static class QingGuiR03InputDiagnostics {
 const string Key="QingGuiR03InputDiagnostics.Run";const string Out=QingGuiR03FirstLook.Logs+"/input-diagnostics-01";static IEnumerator routine;static int frame;static Camera cam;static GameObject item;static Light sun;static RenderTexture target;static Texture2D pixels;static Material jade;static Renderer core;
 static QingGuiR03InputDiagnostics()=>EditorApplication.update+=Boot;
 public static void Run(){Directory.CreateDirectory(Out);EditorSceneManager.OpenScene(QingGuiR03FirstLook.Root+"/QingGuiR03_FirstLook.unity");SessionState.SetBool(Key,true);EditorApplication.EnterPlaymode();}
 static void Boot(){if(!Application.isPlaying||EditorApplication.isCompiling||!SessionState.GetBool(Key,false))return;SessionState.SetBool(Key,false);try{cam=Camera.main;cam.enabled=true;sun=RenderSettings.sun;item=GameObject.Find("R03 Actual three-part object");core=item.GetComponentsInChildren<Renderer>().Single(r=>r.name.Contains("JadeCore"));jade=core.sharedMaterial;target=new RenderTexture(1280,960,24,RenderTextureFormat.ARGB32,RenderTextureReadWrite.Linear){antiAliasing=4};target.Create();pixels=new Texture2D(1280,960,TextureFormat.RGBA32,false,true);QualitySettings.realtimeReflectionProbes=true;new GameObject("R03 input diagnostic tick").AddComponent<QingGuiR03ReviewTick>();QingGuiR03ReviewTick.Tick=Step;routine=Check();}catch(Exception e){Fail(e);}}
 static IEnumerator Check(){var p=Object.FindFirstObjectByType<ReflectionProbe>();int id=p.RenderProbe();for(int i=0;i<100&&!p.IsFinishedRendering(id);i++)yield return null;cam.enabled=false;Shot("01_Original_Mobile");float original=sun.shadowStrength;sun.shadowStrength=0;yield return null;Shot("02_OnlyShadowStrengthZero");var lit=new Material(Shader.Find("Universal Render Pipeline/Lit"));lit.SetColor("_BaseColor",jade.GetColor("_BaseColor"));lit.SetFloat("_Smoothness",jade.GetFloat("_Smoothness"));core.sharedMaterial=lit;yield return null;Shot("03_StandardLit_NoShadows_NoNormalMap");var normals=new Material(Shader.Find("Hidden/QingGuiR03/MeshNormals"));core.sharedMaterial=normals;yield return null;Shot("04_ImportedMeshNormals");core.sharedMaterial=jade;sun.shadowStrength=original;Object.Destroy(lit);Object.Destroy(normals);File.WriteAllText(Out+"/result.txt","Four same-camera controls captured, zero exposure/light-direction changes. The shadow-off images are diagnostics, never a deliverable replacement.\n");EditorApplication.Exit(0);}
 static void Shot(string name){RenderPipeline.SubmitRenderRequest(cam,new UniversalRenderPipeline.SingleCameraRequest{destination=target});var old=RenderTexture.active;RenderTexture.active=target;pixels.ReadPixels(new Rect(0,0,1280,960),0,0);pixels.Apply();RenderTexture.active=old;var gamma=new Texture2D(1280,960,TextureFormat.RGB24,false);gamma.SetPixels(pixels.GetPixels().Select(c=>c.gamma).ToArray());gamma.Apply();File.WriteAllBytes(Out+"/"+name+".png",gamma.EncodeToPNG());Object.Destroy(gamma);}
 static void Step(){try{if(++frame>200)throw new Exception("Diagnostic frame bound");if(!routine.MoveNext())EditorApplication.Exit(0);}catch(Exception e){Fail(e);}}
 static void Fail(Exception e){QingGuiR03ReviewTick.Tick=null;Directory.CreateDirectory(Out);File.WriteAllText(Out+"/failure.txt",e.ToString());EditorApplication.Exit(3);}
}
